#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll mod = 998244353;
bool can(int n, int v, int l, bool rt, const vector<int> &q){
    int r =v-1-l;
    int pos = rt ? n-r:l+1;
    
    for(int i:q){
        int lp = min(i,l);
        int rp=max(0, i-(n-r));
        int cp = lp+rp;
        
        int ls = max(0,l-i+1);
        int rs = min(r,n-i+1);
        int cs = ls+rs;
        
        bool pre = (pos<=i && cp == (i-1)/2);
        bool suf = (pos >=i && cs ==(n-i)/2);
        
        if(!pre && !suf) return false;
    }
    return true;
}
int main() {
	// your code goes here
    ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<vector<int>> at(n+1);
        
        for(int i=1;i<=n;i++){
            int x;
            cin>>x;
            at[x].push_back(i);
        }
        vector<ll> dp(n+1), ndp(n+1);
        dp[0]=1;
        for(int v=1;v<n;v++){
            fill(ndp.begin(),ndp.end(),0);
        for(int l=0;l<v;l++){
            if(!dp[l]) continue;
            if(can(n,v,l,false,at[v])){
                ndp[l+1] += dp[l];
                if(ndp[l+1] >=mod) ndp[l+1]-=mod;
            }
            if(can(n,v,l,true,at[v])){
                ndp[l]+=dp[l];
                if(ndp[l]>=mod) ndp[l]-=mod;
            }
        }
        dp.swap(ndp);
        }
        ll ans =0;
        for(int l=0;l<n;l++){
            if(dp[l] && can(n,n,l,false,at[n])){
                ans += dp[l];
                if(ans >= mod) ans -= mod;
            }
        }
        cout<<ans<<'\n';
        
    }
    return 0;
}
